create function pilot_private.storage_file_cohort(p_name text) returns uuid language sql immutable set search_path='' as $$select case when split_part(p_name,'/',2) ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then split_part(p_name,'/',2)::uuid else null end$$;
revoke all on function pilot_private.storage_file_cohort(text) from public,anon;grant execute on function pilot_private.storage_file_cohort(text) to authenticated,service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('portal-private-files','portal-private-files',false,5242880,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','image/jpeg','image/png']) on conflict(id) do nothing;
create policy portal_private_file_insert on storage.objects for insert to authenticated with check(bucket_id='portal-private-files' and (storage.foldername(name))[1]=auth.uid()::text and pilot_private.portal_role(pilot_private.storage_file_cohort(name)) in ('learner','pilot_owner') and (storage.foldername(name))[3] in ('resume','evidence'));
create policy portal_private_file_read on storage.objects for select to authenticated using(bucket_id='portal-private-files' and ( ((storage.foldername(name))[1]=auth.uid()::text and pilot_private.portal_role(pilot_private.storage_file_cohort(name)) in ('learner','pilot_owner')) or ((storage.foldername(name))[3]='evidence' and pilot_private.portal_role(pilot_private.storage_file_cohort(name))='pilot_owner')));
